INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$SELECT count(*) AS projects,count(*) FILTER (WHERE status IN ('planning','in-progress','in-review','on-hold')) AS active FROM veloryz_studio.studio_client_projects$contract$,'UTF8')),'hex'),$contract$SELECT count(*) AS projects,count(*) FILTER (WHERE status IN ('planning','in-progress','in-review','on-hold')) AS active FROM veloryz_studio.studio_client_projects$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
INSERT INTO veloryz_studio.query_contracts(key,query) VALUES (encode(sha256(convert_to($contract$SELECT a.*,count(*) OVER () AS total_actions FROM (SELECT p.id AS project_id,i.title AS title,p.title AS subtitle,i.due_date AS event_time,'Overdue' AS priority,0 AS rank FROM veloryz_studio.studio_client_items i JOIN veloryz_studio.studio_client_projects p ON p.id=i.project_id WHERE i.type='milestone' AND i.state<>'done' AND i.due_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND i.due_date<? UNION ALL SELECT p.id,i.title,p.title,i.updated_at,CASE WHEN i.state='changes' THEN 'Changes requested' ELSE 'Awaiting client' END,CASE WHEN i.state='changes' THEN 1 ELSE 7 END FROM veloryz_studio.studio_client_items i JOIN veloryz_studio.studio_client_projects p ON p.id=i.project_id WHERE i.type='approval' AND i.state IN ('waiting','changes') UNION ALL SELECT p.id,p.title,count(*)::text || ' unread client messages',max(m.created_at),'Reply',3 FROM veloryz_studio.studio_client_messages m JOIN veloryz_studio.studio_client_projects p ON p.id=m.project_id WHERE m.sender='client' AND coalesce(m.read_at,'')='' GROUP BY p.id,p.title) a ORDER BY rank,event_time DESC,project_id LIMIT 200$contract$,'UTF8')),'hex'),$contract$SELECT a.*,count(*) OVER () AS total_actions FROM (SELECT p.id AS project_id,i.title AS title,p.title AS subtitle,i.due_date AS event_time,'Overdue' AS priority,0 AS rank FROM veloryz_studio.studio_client_items i JOIN veloryz_studio.studio_client_projects p ON p.id=i.project_id WHERE i.type='milestone' AND i.state<>'done' AND i.due_date ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND i.due_date<? UNION ALL SELECT p.id,i.title,p.title,i.updated_at,CASE WHEN i.state='changes' THEN 'Changes requested' ELSE 'Awaiting client' END,CASE WHEN i.state='changes' THEN 1 ELSE 7 END FROM veloryz_studio.studio_client_items i JOIN veloryz_studio.studio_client_projects p ON p.id=i.project_id WHERE i.type='approval' AND i.state IN ('waiting','changes') UNION ALL SELECT p.id,p.title,count(*)::text || ' unread client messages',max(m.created_at),'Reply',3 FROM veloryz_studio.studio_client_messages m JOIN veloryz_studio.studio_client_projects p ON p.id=m.project_id WHERE m.sender='client' AND coalesce(m.read_at,'')='' GROUP BY p.id,p.title) a ORDER BY rank,event_time DESC,project_id LIMIT 200$contract$) ON CONFLICT(key) DO UPDATE SET query=EXCLUDED.query;
